@startuml

class Ingredient {
  + name : string
  + measuring_unit : string
  + quantity_in_stock : float
}

class Dish {
  + name : string
  + id : int
}

class Table {
  + id : int
  + maximum_amount_of_people : int
}

class Meal {
  + date : date
  + start_time : time
  + end_time : time
}

class Waiter {
  + id : int
  + name : string
  + address : string
  + phone : string
}

class Client {
  + tax_identification_number : string
  + name : string
  + address : string
}

class MealDish {
  + quantity : float
}

Dish "1" -- "*" MealDish : contains
Ingredient "1" -- "*" MealDish : used in
Dish "*" -- "*" Ingredient : composed of

Meal "0..1" -- "1" Client : consumed by
Meal "1" -- "1" Waiter : responsible
Meal "*" -- "1" Table : takes place at
Meal "1" -- "1..*" MealDish : includes

@enduml

